19	package org.apache.flink.runtime.state.filesystem;
20	
21	import org.apache.flink.core.fs.FileSystem;
22	import org.apache.flink.core.fs.Path;
23	import org.apache.flink.runtime.checkpoint.filemerging.FileMergingSnapshotManager;
24	import org.apache.flink.runtime.state.CheckpointStorageLocationReference;
25	import org.apache.flink.runtime.state.CheckpointStreamFactory;
26	import org.apache.flink.runtime.state.CheckpointedStateScope;
