28	
29	import java.io.IOException;
30	import java.util.List;
31	import java.util.function.Supplier;
32	
33	/** An implementation of checkpoint storage location for file merging checkpoints. */
34	public class FsMergingCheckpointStorageLocation extends FsCheckpointStorageLocation {
35	
36	    /** ID of the subtask that performs the checkpoint. */
37	    private final FileMergingSnapshotManager.SubtaskKey subtaskKey;
38	
39	    /** The delegate for creating the checkpoint output streams. */
40	    private final FileMergingSnapshotManager fileMergingSnapshotManager;
41	
42	    /** ID of the checkpoint. */
43	    private final long checkpointId;
44	
45	    /** A supplier for converting this location back into a non-fileMerging version. */
46	    private final Supplier<FsCheckpointStorageLocation> backwardsConvertor;
47	
48	    public FsMergingCheckpointStorageLocation(
49	            FileMergingSnapshotManager.SubtaskKey subtaskKey,
50	            FileSystem fileSystem,
51	            Path checkpointDir,
52	            Path sharedStateDir,
53	            Path taskOwnedStateDir,
54	            CheckpointStorageLocationReference reference,
55	            int fileStateSizeThreshold,
56	            int writeBufferSize,
57	            FileMergingSnapshotManager fileMergingSnapshotManager,
58	            long checkpointId) {
59	        super(
60	                fileSystem,
61	                checkpointDir,
62	                sharedStateDir,
63	                taskOwnedStateDir,
64	                reference,
65	                fileStateSizeThreshold,
66	                writeBufferSize);
67	
68	        this.subtaskKey = subtaskKey;
69	        this.checkpointId = checkpointId;
70	        this.fileMergingSnapshotManager = fileMergingSnapshotManager;
71	        this.backwardsConvertor =
72	                () ->
73	                        new FsCheckpointStorageLocation(
74	                                fileSystem,
75	                                checkpointDir,
76	                                sharedStateDir,
77	                                taskOwnedStateDir,
78	                                reference,
79	                                fileStateSizeThreshold,
80	                                writeBufferSize);
81	    }
82	
83	    public CheckpointStreamFactory toNonFileMerging() {
84	        return backwardsConvertor.get();
85	    }
86	
87	    @Override
