33	/**
34	 * A {@link OperatorStreamStateHandle} that works for file merging checkpoints.
35	 *
36	 * <p>Operator states are stored in `taskownd/` dir when file merging is enabled. When an operator
37	 * state dir is not referenced by any checkpoint, {@link SharedStateRegistry} will discard it. The
38	 * shared subtask dir of fire merging is also tracked by {@link
39	 * FileMergingOperatorStreamStateHandle}.
40	 *
41	 * <p>The shared subtask dir of file merging is created when task initialization, which will be
42	 * discarded when no checkpoint refer to it.
43	 */
44	public class FileMergingOperatorStreamStateHandle extends OperatorStreamStateHandle
45	        implements CompositeStateHandle {
46	
47	    private static final long serialVersionUID = 1L;
48	    private static final Logger LOG =
49	            LoggerFactory.getLogger(FileMergingOperatorStreamStateHandle.class);
50	
51	    /** The directory handle of file merging under 'taskowed/', one for each job. */
52	    private final DirectoryStreamStateHandle taskOwnedDirHandle;
53	
54	    /**
55	     * The directory handle of file merging under 'shared/', one for each subtask.
56	     *
57	     * @see org.apache.flink.runtime.checkpoint.filemerging.FileMergingSnapshotManager the layout of
58	     *     file merging checkpoint directory.
59	     */
60	    private final DirectoryStreamStateHandle sharedDirHandle;
61	
62	    private transient SharedStateRegistry sharedStateRegistry;
63	
64	    public FileMergingOperatorStreamStateHandle(
65	            DirectoryStreamStateHandle taskOwnedDirHandle,
66	            DirectoryStreamStateHandle sharedDirHandle,
67	            Map<String, StateMetaInfo> stateNameToPartitionOffsets,
68	            StreamStateHandle delegateStateHandle) {
69	        super(stateNameToPartitionOffsets, delegateStateHandle);
70	        this.taskOwnedDirHandle = taskOwnedDirHandle;
71	        this.sharedDirHandle = sharedDirHandle;
72	    }
73	
74	    @Override
75	    public void registerSharedStates(SharedStateRegistry stateRegistry, long checkpointId) {
76	        Preconditions.checkState(
77	                sharedStateRegistry != stateRegistry,
78	                "The state handle has already registered its shared states to the given registry.");
79	
80	        sharedStateRegistry = Preconditions.checkNotNull(stateRegistry);
81	
82	        LOG.trace(
83	                "Registering FileMergingOperatorStreamStateHandle for checkpoint {} from backend.",
84	                checkpointId);
85	        // Only register the directory here, leave the delegateStateHandle unregistered, since the
86	        // OperatorSubtaskState will only take care of the keyed state while leaving others
87	        // unregistered.
88	        stateRegistry.registerReference(
89	                taskOwnedDirHandle.createStateRegistryKey(), taskOwnedDirHandle, checkpointId);
90	        stateRegistry.registerReference(
91	                sharedDirHandle.createStateRegistryKey(), sharedDirHandle, checkpointId);
92	    }
93	
94	    @Override
95	    public void discardState() throws Exception {
96	        SharedStateRegistry registry = this.sharedStateRegistry;
97	        final boolean isRegistered = (registry != null);
98	
99	        LOG.trace(
100	                "Discarding FileMergingOperatorStreamStateHandle (registered = {}) from backend.",
101	                isRegistered);
102	
103	        try {
104	            getDelegateStateHandle().discardState();
105	        } catch (Exception e) {
106	            LOG.warn("Could not properly discard directory state handle.", e);
107	        }
108	    }
109	
110	    @Override
111	    public long getCheckpointedSize() {
112	        return getDelegateStateHandle().getStateSize();
113	    }
114	
115	    public DirectoryStreamStateHandle getSharedDirHandle() {
116	        return sharedDirHandle;
117	    }
118	
119	    public DirectoryStreamStateHandle getTaskOwnedDirHandle() {
120	        return taskOwnedDirHandle;
121	    }
122	
123	    @Override
124	    public boolean equals(Object o) {
125	        if (this == o) {
126	            return true;
127	        }
128	
129	        if (o == null || getClass() != o.getClass()) {
130	            return false;
131	        }
132	
133	        FileMergingOperatorStreamStateHandle that = (FileMergingOperatorStreamStateHandle) o;
134	
135	        return super.equals(that)
136	                && taskOwnedDirHandle.equals(that.taskOwnedDirHandle)
137	                && sharedDirHandle.equals(that.sharedDirHandle);
138	    }
139	
140	    @Override
141	    public int hashCode() {
142	        int result = super.hashCode();
143	        result = 31 * result + Objects.hashCode(taskOwnedDirHandle);
144	        result = 31 * result + Objects.hashCode(sharedDirHandle);
145	        return result;
146	    }
147	
148	    @Override
149	    public String toString() {
150	        return "FileMergingOperatorStreamStateHandle{"
151	                + super.toString()
152	                + ", taskOwnedDirHandle="
153	                + taskOwnedDirHandle
154	                + ", sharedDirHandle="
155	                + sharedDirHandle
156	                + '}';
157	    }
158	}
